"""Plain text absence notices for parents."""

from rosterkit.models import Student
from rosterkit.errors import ProjectError

# ---
def absence_notice(student: Student, marks: list) -> str:
    """Build a short notice listing the absent days."""
    for mark in marks:
        if mark.student_id != student.student_id:
            raise ProjectError(
                f"mark belongs to {mark.student_id}"
            )
    dates = sorted(
        mark.day for mark in marks if mark.status == "absent"
    )
    if not dates:
        raise ProjectError("no absences to report")
    listed = ", ".join(item.isoformat() for item in dates)
    return (
        f"{student.first_name} {student.last_name} "
        f"missed {len(dates)} day(s): {listed}"
    )
